   1 | int copy_creds(struct task_struct *p, unsigned long clone_flags)
   2 | {
   3 | // #ifdef CONFIG_KEYS
   4 | 	struct thread_group_cred *tgcred;
   5 | #endif
   6 | 	struct cred *new;
   7 | 	int ret;
   8 | 
   9 | 	if (
  10 | // #ifdef CONFIG_KEYS
  11 | 		!p->cred->thread_keyring &&
  12 | #endif
  13 | 		clone_flags & CLONE_THREAD
  14 | 	    ) {
  15 | 		p->real_cred = get_cred(p->cred);
  16 | 		get_cred(p->cred);
  17 | 		alter_cred_subscribers(p->cred, 2);
  18 | 		kdebug("share_creds(%p{%d,%d})",
  19 | 		       p->cred, atomic_read(&p->cred->usage),
  20 | 		       read_cred_subscribers(p->cred));
  21 | 		atomic_inc(&p->cred->user->processes);
  22 | 		return 0;
  23 | 	}
  24 | 
  25 | 	new = prepare_creds();
  26 | 	if (!new)
  27 | 		return -ENOMEM;
  28 | 
  29 | 	if (clone_flags & CLONE_NEWUSER) {
  30 | 		ret = create_user_ns(new);
  31 | 		if (ret < 0)
  32 | 			goto error_put;
  33 | 	}
  34 | 
  35 | 	/* cache user_ns in cred.  Doesn't need a refcount because it will
  36 | 	 * stay pinned by cred->user
  37 | 	 */
  38 | 	new->user_ns = new->user->user_ns;
  39 | 
  40 | // #ifdef CONFIG_KEYS
  41 | 	/* new threads get their own thread keyrings if their parent already
  42 | 	 * had one */
  43 | 	if (new->thread_keyring) {
  44 | 		key_put(new->thread_keyring);
  45 | 		new->thread_keyring = NULL;
  46 | 		if (clone_flags & CLONE_THREAD)
  47 | 			install_thread_keyring_to_cred(new);
  48 | 	}
  49 | 
  50 | 	/* we share the process and session keyrings between all the threads in
  51 | 	 * a process - this is slightly icky as we violate COW credentials a
  52 | 	 * bit */
  53 | 	if (!(clone_flags & CLONE_THREAD)) {
  54 | 		tgcred = kmalloc(sizeof(*tgcred), GFP_KERNEL);
  55 | 		if (!tgcred) {
  56 | 			ret = -ENOMEM;
  57 | 			goto error_put;
  58 | 		}
  59 | 		atomic_set(&tgcred->usage, 1);
  60 | 		spin_lock_init(&tgcred->lock);
  61 | 		tgcred->process_keyring = NULL;
  62 | 		tgcred->session_keyring = key_get(new->tgcred->session_keyring);
  63 | 
  64 | 		release_tgcred(new);
  65 | 		new->tgcred = tgcred;
  66 | 	}
  67 | #endif
  68 | 
  69 | 	atomic_inc(&new->user->processes);
  70 | 	p->cred = p->real_cred = get_cred(new);
  71 | 	alter_cred_subscribers(new, 2);
  72 | 	validate_creds(new);
  73 | 	return 0;
  74 | 
  75 | error_put:
  76 | 	put_cred(new);
  77 | 	return ret;
  78 | }
  79 | 
</FUNCTION_SOURCE>
<CLAIM evidence_lines="47, 54, 55, 56, 57, 58, 59, 60, 61, 62, 64, 65">
mechanism: The function is shown with preprocessor directives commented out, so the CONFIG_KEYS-only code (lines 40-67) is unconditionally compiled. When CONFIG_KEYS is disabled, struct thread_group_cred and its fields (usage, lock, process_keyring, session_keyring) do not exist, and new->tgcred is not a valid member, so the kmalloc/field-initialization block at lines 54-65 references nonexistent types and members, causing a compile failure or, if the struct layout differs, out-of-bounds/type-confused writes to the allocated tgcred object. Additionally, install_thread_keyring_to_cred at line 47 is called without checking its return value, and the tgcred allocation path at 54-65 is reached with new->tgcred dereferenced at line 62 without a NULL check.
</CLAIM>

