   1 | static int logi_dj_raw_event(struct hid_device *hdev,
   2 | 			     struct hid_report *report, u8 *data,
   3 | 			     int size)
   4 | {
   5 | 	struct dj_receiver_dev *djrcv_dev = hid_get_drvdata(hdev);
   6 | 	struct dj_report *dj_report = (struct dj_report *) data;
   7 | 	unsigned long flags;
   8 | 	bool report_processed = false;
   9 | 
  10 | 	dbg_hid("%s, size:%d\n", __func__, size);
  11 | 
  12 | 	/* Here we receive all data coming from iface 2, there are 4 cases:
  13 | 	 *
  14 | 	 * 1) Data should continue its normal processing i.e. data does not
  15 | 	 * come from the DJ collection, in which case we do nothing and
  16 | 	 * return 0, so hid-core can continue normal processing (will forward
  17 | 	 * to associated hidraw device)
  18 | 	 *
  19 | 	 * 2) Data is from DJ collection, and is intended for this driver i. e.
  20 | 	 * data contains arrival, departure, etc notifications, in which case
  21 | 	 * we queue them for delayed processing by the work queue. We return 1
  22 | 	 * to hid-core as no further processing is required from it.
  23 | 	 *
  24 | 	 * 3) Data is from DJ collection, and informs a connection change,
  25 | 	 * if the change means rf link loss, then we must send a null report
  26 | 	 * to the upper layer to discard potentially pressed keys that may be
  27 | 	 * repeated forever by the input layer. Return 1 to hid-core as no
  28 | 	 * further processing is required.
  29 | 	 *
  30 | 	 * 4) Data is from DJ collection and is an actual input event from
  31 | 	 * a paired DJ device in which case we forward it to the correct hid
  32 | 	 * device (via hid_input_report() ) and return 1 so hid-core does not do
  33 | 	 * anything else with it.
  34 | 	 */
  35 | 	if ((dj_report->device_index < DJ_DEVICE_INDEX_MIN) ||
  36 | 	    (dj_report->device_index > DJ_DEVICE_INDEX_MAX)) {
  37 | 		dev_err(&hdev->dev, "%s: invalid device index:%d\n",
  38 | 				__func__, dj_report->device_index);
  39 | 		return false;
  40 | 	}
  41 | 
  42 | 	spin_lock_irqsave(&djrcv_dev->lock, flags);
  43 | 	if (dj_report->report_id == REPORT_ID_DJ_SHORT) {
  44 | 		switch (dj_report->report_type) {
  45 | 		case REPORT_TYPE_NOTIF_DEVICE_PAIRED:
  46 | 		case REPORT_TYPE_NOTIF_DEVICE_UNPAIRED:
  47 | 			logi_dj_recv_queue_notification(djrcv_dev, dj_report);
  48 | 			break;
  49 | 		case REPORT_TYPE_NOTIF_CONNECTION_STATUS:
  50 | 			if (dj_report->report_params[CONNECTION_STATUS_PARAM_STATUS] ==
  51 | 			    STATUS_LINKLOSS) {
  52 | 				logi_dj_recv_forward_null_report(djrcv_dev, dj_report);
  53 | 			}
  54 | 			break;
  55 | 		default:
  56 | 			logi_dj_recv_forward_report(djrcv_dev, dj_report);
  57 | 		}
  58 | 		report_processed = true;
  59 | 	}
  60 | 	spin_unlock_irqrestore(&djrcv_dev->lock, flags);
  61 | 
  62 | 	return report_processed;
  63 | }
  64 | 
</FUNCTION_SOURCE>
<CLAIM evidence_lines="6, 35, 36, 43, 50, 56">
mechanism: The function casts the raw HID report buffer 'data' to struct dj_report and dereferences fields (device_index, report_id, report_type, report_params) without checking that 'size' is at least sizeof(struct dj_report). A short report from the device causes out-of-bounds reads of the buffer, and the validated device_index is then used by logi_dj_recv_forward_report/queue_notification to index into arrays.
</CLAIM>

