   1 | static int modify_bitmap(const char *str, unsigned long *bitmap, int bits)
   2 | {
   3 | 	int a, i, z;
   4 | 	char *np, sign;
   5 | 
   6 | 	/* bits needs to be a multiple of 8 */
   7 | 	if (bits & 0x07)
   8 | 		return -EINVAL;
   9 | 
  10 | 	while (*str) {
  11 | 		sign = *str++;
  12 | 		if (sign != '+' && sign != '-')
  13 | 			return -EINVAL;
  14 | 		a = z = simple_strtoul(str, &np, 0);
  15 | 		if (str == np || a >= bits)
  16 | 			return -EINVAL;
  17 | 		str = np;
  18 | 		if (*str == '-') {
  19 | 			z = simple_strtoul(++str, &np, 0);
  20 | 			if (str == np || a > z || z >= bits)
  21 | 				return -EINVAL;
  22 | 			str = np;
  23 | 		}
  24 | 		for (i = a; i <= z; i++)
  25 | 			if (sign == '+')
  26 | 				set_bit_inv(i, bitmap);
  27 | 			else
  28 | 				clear_bit_inv(i, bitmap);
  29 | 		while (*str == ',' || *str == '\n')
  30 | 			str++;
  31 | 	}
  32 | 
  33 | 	return 0;
  34 | }
  35 | 
</FUNCTION_SOURCE>
<CLAIM evidence_lines="14, 15, 19, 20, 24">
mechanism: simple_strtoul returns unsigned long but is stored into int a and z; a value >= 2^31 (or > INT_MAX) truncates to a negative int. The check a >= bits compares the truncated negative value, which passes, and the loop for (i = a; i <= z; i++) then uses a negative index, causing out-of-bounds set_bit_inv/clear_bit_inv on the bitmap.
</CLAIM>

